export function shapeRings(n,time=0){if(n.type==='group'||n.type==='text')throw Error('Select the shapes inside the group; text cannot be combined.');const v=clone(evaluated(n,time));convertToPath(v);const m=matrix(v),rings=[];let ring=[],start=null,prev=null;const mapped=p=>{const q=point(m,p);for(const side of ['in','out'])if(p[side])q[side]=point(m,p[side]);return q;};const finish=()=>{if(ring.length>=3){if(prev&&start)flatten(prev,start,ring);if(Math.abs(area(ring))>.001)rings.push(ring);}ring=[];};for(const node of v.nodes){const p=mapped(node);if(node.move||!prev){if(ring.length)finish();ring=[[p.x,p.y]];start=p;}else flatten(prev,p,ring);prev=p;if(node.close){finish();prev=null;}}if(ring.length){if(!v.closed)throw Error('Close open paths before combining shapes.');finish();}if(!rings.length)throw Error('Choose filled shapes with a closed area.');return rings;}
