export function joinPaths(doc,ids,time=0){const roots=selectionRoots(doc,ids);if(roots.length!==2||roots.some(n=>n.closed||n.nodes.some(p=>p.close)||!['path','freehand'].includes(n.type)||isLocked(doc,n.id)))throw Error('Select two unlocked open paths to join.');const locations=roots.map(n=>locate(doc,n.id));if(locations[0].list!==locations[1].list)throw Error('Choose paths in the same group.');const arrays=roots.map(n=>{const v=evaluated(n,time),m=matrix(v);return v.nodes.map(p=>{const q={...p,...point(m,p)};for(const side of ['in','out'])if(p[side])q[side]=point(m,p[side]);return q;});});if(arrays.some(a=>a.length<2||a.some((p,i)=>i&&p.move)))throw Error('Join simple open paths with at least two points.');const reverse=a=>[...a].reverse().map(p=>({...p,in:p.out,out:p.in})),choices=[arrays,[reverse(arrays[0]),arrays[1]],[arrays[0],reverse(arrays[1])],[reverse(arrays[0]),reverse(arrays[1])]].sort((a,b)=>Math.hypot(a[0].at(-1).x-a[1][0].x,a[0].at(-1).y-a[1][0].y)-Math.hypot(b[0].at(-1).x-b[1][0].x,b[0].at(-1).y-b[1][0].y)),[a,b]=choices[0];delete a.at(-1).out;delete b[0].in;for(const p of [...a,...b]){delete p.move;delete p.close;}const v=evaluated(roots[0],time),n=object('path',{name:'Joined path',nodes:[...a,...b],fill:'none',stroke:v.stroke==='none'?v.fill:v.stroke,strokeWidth:Math.max(2,v.strokeWidth)}),list=locations[0].list,index=Math.min(...locations.map(l=>l.index));for(let i=list.length-1;i>=0;i--)if(roots.includes(list[i]))list.splice(i,1);list.splice(index,0,n);return n;}
